final Path _smallMark = parseSvgPath(brandMarkPath);
final Path _fullMark = parseSvgPath(brandMarkFullPath);

class BrandMark extends StatelessWidget {
  const BrandMark({this.size = 36, this.color, super.key});

  final double size;
  final Color? color;

  @override
  Widget build(BuildContext context) {
    final ink = color ?? NbColors.of(context).primary;
    return ExcludeSemantics(
      child: CustomPaint(
        size: Size.square(size),
        painter: _BrandMarkPainter(color: ink, small: size <= _smallLimit),
      ),
    );
  }
}

class _BrandMarkPainter extends CustomPainter {
  const _BrandMarkPainter({required this.color, required this.small});

  final Color color;
  final bool small;

  @override
  void paint(Canvas canvas, Size size) {
    final path = small ? _smallMark : _fullMark;
    path.fillType = PathFillType.evenOdd;
    canvas.save();
    canvas.scale(size.width / _markBox, size.height / _markBox);
    canvas.drawPath(
      path,
      Paint()
        ..style = PaintingStyle.fill
        ..color = color,
    );
    canvas.restore();
  }

  @override
  bool shouldRepaint(_BrandMarkPainter oldDelegate) =>
      oldDelegate.color != color || oldDelegate.small != small;
}
